import RNA, random, multiprocessing as mp
target='.....(((((((.(((((....)))).)))(((((.((..((((....))))..(((((......)))))..)).))))))))))....................'
def worker(seed):
    random.seed(seed)
    for _ in range(300):
        start=''.join(random.choice('ACGU') for _ in range(len(target)))
        seq, d = RNA.inverse_fold(start, target)
        if d == 0.0 and RNA.fold_compound(seq).mfe()[0] == target:
            return seq
    return None
if __name__ == '__main__':
    with mp.Pool(64) as p:
        for r in p.imap_unordered(worker, range(640)):
            if r:
                print('SOLVED', r)
                p.terminate(); break
" 2>&1 | head -5

